"""Build an additive, static NBA Pages site from a checked official-game sample."""
from pathlib import Path
from html import escape as e
import importlib.util

BASE = Path(__file__).parent
spec=importlib.util.spec_from_file_location('compute', BASE/'compute.py')
c=importlib.util.module_from_spec(spec); spec.loader.exec_module(c)
rows=c.load(); corrs=c.correlations(rows)
LOG='https://www.nba.com/stats/player/1630162/boxscores?Season=2025-26'
INJ='https://official.nba.com/nba-injury-report-2026-27-season/'
TEAMS='https://www.nba.com/stats/teams/traditional?Season=2025-26&SeasonType=Regular%20Season'
NAV=[('index.html','Overview'),('summary.html','Executive summary'),('sample.html','Official game data'),('correlations.html','Correlations'),('strategies.html','Strategies'),('gates.html','Validation gates'),('leaderboard.html','Leaderboard'),('review.html','Flagged for Review')]
def link(url, name='NBA source'):
    assert url.startswith(('https://www.nba.com/','https://official.nba.com/'))
    return f'<a href="{e(url,quote=True)}" target="_blank" rel="noopener noreferrer">{e(name)}</a>'
def table(headers, records):
    return '<div class="scroll"><table><thead><tr>'+''.join(f'<th scope="col">{e(h)}</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{cell}</td>' for cell in row)+'</tr>' for row in records)+'</tbody></table></div>'
def page(title, intro, content):
    nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if title==label else '')+f'>{label}</a>' for url,label in NAV)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)} · Own5 NBA</title><link rel="stylesheet" href="style.css"></head><body><header><div class="wrap"><p class="eyebrow">OWN5 / NBA RESEARCH</p><h1>NBA line lab</h1><p>Evidence first. No eligible bets, no simulated rewards.</p><nav aria-label="NBA lab">{nav}</nav></div></header><main class="wrap"><div class="heading"><p class="eyebrow">2026–27 research workspace · reviewed 3 Nov 2026</p><h2>{e(title)}</h2><p class="lead">{e(intro)}</p></div>{content}</main><footer class="wrap">Independent research. Descriptive historical correlations are not probabilities or betting edges. No wagers recommended. <a href="../docs/">Earlier NBA lab</a> · <a href="../">Repository dashboard</a></footer></body></html>'''
def write(name, title, intro, body): (BASE/name).write_text(page(title,intro,body),encoding='utf8')

write('index.html','Overview','A compact dashboard for source-linked NBA data and gated strategy research. Historical data is not a live quote.',f'''<div class="cards"><article><strong>10</strong><span>NBA game-log rows</span></article><article><strong>5</strong><span>exploratory correlations</span></article><article><strong>0</strong><span>validated strategies</span></article><article><strong>0</strong><span>rewards paid</span></article></div><section><h3>What is available?</h3>{table(['Workstream','Current finding','Official evidence'],[['Singles','Candidate model only; no current market prices',link(TEAMS,'Team statistics')],['Player props','Ten official player-games available for a descriptive sample',link(LOG,'Player game log')],['Parlays / prop combos','Pairwise coefficients on a small selected sample; no joint odds',link(LOG,'Player game log')],['Injury response','Official reporting cadence documented; no timestamped odds',link(INJ,'Injury report')]])}</section><section class="notice"><h3>Decision</h3><p>All strategies are <b>blocked</b>. Outcome data alone cannot establish a forecast edge: no pre-bet quotes, closing prices, out-of-sample predictions or settled bet ledger are available. See <a href="review.html">Flagged for Review</a>.</p></section>''')
write('summary.html','Executive summary','The key decisions, evidence and blockers in one place.',f'''{table(['Priority','Finding / decision','Official evidence'],[['1 · Scope','Originate independent NBA probabilities for singles, props and combinations; not a copy of sportsbook prices. This is a proposed design, not an observed advantage.',link(TEAMS,'NBA team data')],['2 · Evidence','Ten Anthony Edwards player-games from 2025–26 are transcribed with official game links. Selection: first ten displayed on the player log, most recent first.',link(LOG,'NBA player game log')],['3 · Dependence','Five Pearson coefficients are computed on n=10; they describe this player and period only, not league-wide relationships or market value.',link(LOG,'NBA player game log')],['4 · Injury timing','Use official report releases as time-stamped inputs, but no priced injury signal can be validated without contemporaneous odds.',link(INJ,'NBA injury reports')],['5 · Competition','No strategy passes the gates. Leaderboard and prize awards remain empty; proposed awards are conditional on a funded prize pool and approved rules.',link(LOG,'NBA outcomes input')]])}<section class="notice"><h3>Bottom line</h3><p>Keep research separate from wagering. No amount of historical correlation removes luck: gatekeeping, prospective logging and uncertainty intervals can reduce false discoveries, not guarantee profit.</p></section>''')
write('sample.html','Official game data','Most recent ten displayed 2025–26 Anthony Edwards regular-season player log entries; manually transcribed on 3 Nov 2026.',table(['Date','Opponent','W/L','MIN','PTS','3PM','REB','AST','Official NBA game'],[[e(r['date']),e(r['opponent']),e(r['result']),str(r['minutes']),str(r['points']),str(r['threes']),str(r['rebounds']),str(r['assists']),link(r['source'],r['game_id'])] for r in rows])+f'<p class="note">Primary cross-check: {link(LOG,"official player game log")}. A game page may default to a team summary; use the player log for these player stats. This selected, small sample is not representative.</p>')
write('correlations.html','Correlations','Sample Pearson r of paired game-level observations. Derived by compute.py from the NBA player log; no implied odds, confidence or causal claim.',table(['Pair','Pearson r','n','Interpretation','Official input'],[[e(x.title()+' × '+y.title()),f'{v:+.4f}','10','Descriptive · selected player/game sample',link(LOG,'NBA player game log')] for x,y,v in corrs])+'''<section><h3>Calculation & scope</h3><p>r = Σ(x−x̄)(y−ȳ) / √[Σ(x−x̄)² Σ(y−ȳ)²]. “Win” is 1 for W and 0 for L; Pearson with binary win is a point-biserial correlation. No rounding before calculation. Recompute with <code>python3 nba-2026-lab/compute.py</code>. A 3PM–PTS link is partly arithmetic (made threes contribute points); this is not an independent signal. Only same-player/game continuous outcome dependence is shown; correlations between binary leg hits at a quoted line, across games, or conditional on injury remain <b>blank / unverified</b>.</p></section>''')
strategies=[('S1','Single · moneyline','Fit calibrated win probabilities using only pre-tip team data; compare to de-vigged quote','Team aggregates are official inputs, not proof of a profitable signal',TEAMS),('S2','Single · total/spread','Estimate score distributions with pre-tip pace and roster availability; score against a logged line','No joint game-level input or quote archived',TEAMS),('S3','Player prop · points','Model minutes × usage × scoring conditional on published availability; freeze before tip','Official outcomes exist; no historical injury/price join archived',INJ),('S4','Player prop · assists/rebounds','Separate minutes and role forecasts; model uncertainty and opponent context','Sample player log does not validate prospective props',LOG),('S5','Parlay · separate games','Multiply *joint* conditional simulations, audit shared slate shocks, compare joint fair price to actual payout','No parlay payout snapshots available',TEAMS),('S6','Same-game combo · PTS/3PM','Simulate both legs from a joint player-game distribution; evaluate threshold-hit joint frequency and quoted SGP payout','3PM contributes mechanically to PTS; r alone is insufficient',LOG),('S7','Same-game combo · PTS/W','Condition on team win and player scoring; compare priced joint event with simulator','Small selected r is not a joint probability',LOG)]
write('strategies.html','Strategies','Candidate signal designs only. Each requires pre-registration, real quotes and a chronological holdout before ranking.',table(['ID','Market','Origination rule (hypothesis)','Current blocker','Official input'],[[e(*r[:1]),e(r[1]),e(r[2]),e(r[3]),link(r[4])] for r in strategies]))
gates=[('G0','Provenance','All inputs and outcomes linked to official NBA records; timestamp inputs before tip',LOG),('G1','Pre-registration','Freeze strategy, features, thresholds, bet universe and all attempted variants before holdout',TEAMS),('G2','Chronology','Walk-forward training/validation/untouched test by date; no future injury or outcome leakage',INJ),('G3','Calibration','Show out-of-sample reliability, Brier/log loss vs fixed baseline and uncertainty intervals',TEAMS),('G4','Market comparison','Archive executable bet and closing quotes; remove vig and apply stake limits/fees',TEAMS),('G5','Multiplicity','Adjust uncertainty across all tried strategies, markets and parameters; reject fragile discoveries',LOG),('G6','Joint pricing','Use empirical joint hit frequency with thresholds, uncertainty and actual SGP payout; never multiply correlated legs blindly',LOG),('G7','Skill audit','Pre-registered positive net edge and close comparison on untouched paper ledger, with realistic variance/ROI bounds',TEAMS),('G8','Risk & eligibility','Apply bankroll constraints and locally applicable rules; no prize before documented independent approval',INJ)]
write('gates.html','Validation gates','Every gate must pass; thresholds for acceptance must be pre-registered before testing. Links identify official NBA inputs, not external endorsement of the gate.',table(['Gate','Check','Pass condition (proposed)','Official NBA input'],[[e(i),e(t),e(d),link(u)] for i,t,d,u in gates])+'''<p class="note">Status: all <b>pending/blocked</b>. No quote history, prospective holdout or contest funding is present; no strategy can currently pass all gates.</p>''')
write('leaderboard.html','Leaderboard','A competition design, not a performance claim. No ranked entrants or prize commitments.',table(['Division','Eligible entries','Scoring plan (proposal)','Reward status','Official outcomes input'],[[e(t),'0','Rank only strategies passing G0–G8; compare pre-registered out-of-sample net yield and calibration','Not funded; no award',link(LOG)] for t in ['Singles','Player props','Parlays / prop combos']])+'''<p class="note">Prize amounts and entrant names: <b>blank / unverified</b>. Keep a timestamped immutable forecast/quote ledger and publish all attempted variants before any leaderboard ranking.</p>''')
flags=[('F01','Official log is a selected ten-game player sample, not a full league population; correlations should not be generalized.',LOG),('F02','No timestamped bookmaker quotes, vig, limits or closing prices; numeric fair/current edges blank.',TEAMS),('F03','No pre-registered out-of-sample predictions, bet ledger or settlement; strategy performance and payouts blank.',LOG),('F04','No official quoted SGP payouts or binary leg thresholds; joint hit rate and parlay value blank.',LOG),('F05','The older NBA lab uses third-party guides for qualitative correlations; their directional claims are not verified by these ten games.',LOG),('F06','No archived paired injury-report/odds snapshots; injury signal effect remains unverified.',INJ),('F07','Prize pool, jurisdiction and operator rules not documented here; awards blank, pending approval.',INJ),('F08','Previously published NBA summary says 2026-11-02 and older NBA site remains separate; new sample is not a retrofit of that content.',LOG)]
write('review.html','Flagged for Review','Unverified items are visible, non-blocking for publication, and never used as winning strategy claims.',table(['Flag','Issue / missing value','Official source for review'],[[e(i),e(d),link(u)] for i,d,u in flags]))
print(f'Built {len(NAV)} pages; {len(rows)} linked game rows, {len(corrs)} exploratory coefficients')
